  let channel = null;
  let baseUrl = null;
  let candidates = [];
  if (feedUrl) {
    const m = /([^\\/]+)\.ya?ml$/i.exec(feedUrl);
    channel = m ? m[1] : "override";
    provider = "override";
    candidates = [feedUrl];
