      "content": "\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nimport { writeFile, appendFile, rm, mkdir, mkdtemp, readdir, lstat, readFile, cp, realpath, symlink } from \"node:fs/promises\";\nimport { readFileSync, existsSync } from \"node:fs\";\nimport { spawn } from \"node:child_process\";\nimport { join, dirname } from \"node:path\";\nimport { createRequire } from \"node:module\";\nimport { fileURLToPath } from \"node:url\";\nimport { tmpdir } from \"node:os\";\nimport http from \"node:http\";\nimport https from \"node:https\";\nimport { gunzipSync } from \"node:zlib\";\n\n\nimport { resolveNodeExe, getNpmCli, findDshPackageDir, listDshPackageDirs, looksLikeFileLockError, installWithFileLockRetry, shouldResetStaleLock, collectPortPids, servicePidsOnPort, portAlive, killPid, probePortOpen, findLauncherFile, buildServiceRelaunch, countNpmTarballFetches, parseNpmPackageCount, parseNpmRemoveList, formatRemovedPackages, packageProgressPercent, satisfies, compareVersions as compareSemverVersions } from \"../lib/index.js\";\n\nconst ROOT = process.env.DSH_UC_UPDATE_ROOT;\nconst TARGET = process.env.DSH_UC_UPDATE_TARGET;\nconst BACKUP = process.env.DSH_UC_UPDATE_BACKUP;\nconst PROGRESS_FILE = process.env.DSH_UC_UPDATE_PROGRESS;\nconst OPS_FILE = process.env.DSH_UC_UPDATE_OPS;\nconst DSH_HOME = process.env.DSH_UC_UPDATE_DSH_HOME || dirname(dirname(dirname(ROOT)));\nconst SELF_DIR = process.env.DSH_UC_UPDATE_SELF_DIR;\nconst PREV_INSTANCE = process.env.DSH_UC_UPDATE_PREV_INSTANCE || \"\";\nconst PACKAGE = \"@deepseek-ai/dsh\";\n\nif (!ROOT || !TARGET || !BACKUP || !PROGRESS_FILE || !OPS_FILE) {\n  console.error(\"missing required env\");\n  process.exit(2);\n}\n\nconst truncate = (s, n) => {\n  const str = String(s || \"\");\n  return str.length > n ? str.slice(0, n) + \"…(truncated)\" : str;\n};\n\nlet progressCache = null;\nlet progressFrozen = false;\n\nasync function writeProgress(patch) {\n  try {\n    const merged = { running: true, workerPid: process.pid, ...(progressCache ||